# gan_claim.py
# ============================================================
# Claim-level GAN augmentation - Version 2
#
# Main changes from Version 1:
#
# 1. Positive continuous variables:
#       claim_size
#       notidel
#       setldel
#
#    are transformed by:
#       log1p -> StandardScaler -> GAN
#       GAN -> inverse StandardScaler -> expm1
#
# 2. occurrence_period and occurrence_time remain
#    on their original scale.
#
# 3. no_payment remains on its original scale.
#    NO rounding and NO clipping are applied.
#
# 4. All six variables are genuinely generated by GAN.
#
# 5. Synthetic data are merged with original training data
#    at a 1:1 ratio.
#
# 6. Additional GAN fidelity diagnostics are reported:
#       - mean
#       - std
#       - quantiles
#       - minimum / maximum
#       - negative-value proportion
#       - KS statistic / p-value
#
# 7. LightGBM settings are intentionally kept unchanged
#    from Version 1 so that GAN changes can be evaluated
#    independently.
# ============================================================


import os
import random

import numpy as np
import pandas as pd

import torch
import torch.nn as nn
import torch.optim as optim

from torch.utils.data import DataLoader, TensorDataset

from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    mean_squared_error,
    mean_absolute_error
)
from scipy.stats import ks_2samp

import lightgbm as lgb
from lightgbm import LGBMRegressor


