# ============================================================
# 2. Random seed
# ============================================================

SEED = 46


def set_seed(seed=42):

    random.seed(seed)

    np.random.seed(seed)

    torch.manual_seed(seed)

    if torch.cuda.is_available():

        torch.cuda.manual_seed(seed)

        torch.cuda.manual_seed_all(seed)

    torch.backends.cudnn.deterministic = True

    torch.backends.cudnn.benchmark = False


set_seed(SEED)


# ============================================================
# 3. Device
# ============================================================

DEVICE = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("=" * 70)
print("Device:", DEVICE)
print("=" * 70)


# ============================================================
# 4. GAN configuration
# ============================================================

NOISE_DIM = 32

GAN_HIDDEN_DIM = 128

GAN_EPOCHS = 200

GAN_BATCH_SIZE = 256

GAN_LR = 2e-4

GAN_BETA1 = 0.5

GAN_BETA2 = 0.9

# 1.0 = same number of synthetic and real claims
SYNTHETIC_CLAIMS_RATIO = 1.0


# ============================================================
# 5. LightGBM configuration
#
# IMPORTANT:
# Keep unchanged for now.
# We first isolate the effect of GAN design.
# ============================================================

LGB_N_ESTIMATORS = 2000

LGB_LEARNING_RATE = 0.05

LGB_NUM_LEAVES = 31

VALIDATION_SIZE = 0.10

EARLY_STOPPING_ROUNDS = 50

LGB_RANDOM_STATE = 42


# ============================================================
# 6. Claim variables
# ============================================================

ALL_CLAIM_COLUMNS = [
    "claim_no",
    "occurrence_period",
    "occurrence_time",
    "claim_size",
    "notidel",
    "setldel",
    "no_payment"
]

GAN_FEATURES = [
    "occurrence_period",
    "occurrence_time",
    "claim_size",
    "notidel",
    "setldel",
    "no_payment"
]

# Positive continuous variables.
# These are transformed using log1p.
LOG_FEATURES = [
    "claim_size",
    "notidel",
    "setldel"
]

# Kept in original scale.
RAW_FEATURES = [
    "occurrence_period",
    "occurrence_time",
    "no_payment"
]


# ============================================================
# 7. Tabular GAN
# ============================================================

class TabGenerator(nn.Module):

    def __init__(
        self,
        noise_dim,
        out_dim,
        hidden_dim=128
    ):

        super().__init__()

        self.model = nn.Sequential(

            nn.Linear(
                noise_dim,
                hidden_dim
            ),

            nn.ReLU(),

            nn.Linear(
                hidden_dim,
                hidden_dim
            ),

            nn.ReLU(),

            nn.Linear(
                hidden_dim,
                out_dim
            )
        )

    def forward(self, z):

        return self.model(z)


class TabDiscriminator(nn.Module):

    def __init__(
        self,
        in_dim,
        hidden_dim=128
    ):

        super().__init__()

        self.model = nn.Sequential(

            nn.Linear(
                in_dim,
                hidden_dim
            ),

            nn.LeakyReLU(
                0.2
            ),

            nn.Linear(
                hidden_dim,
                64
            ),

            nn.LeakyReLU(
                0.2
            ),

            nn.Linear(
                64,
                1
            ),

            nn.Sigmoid()
        )

    def forward(self, x):

        return self.model(x)


# ============================================================
# 8. Transform training data
# ============================================================

def transform_claim_features(
    train_df
):

    transformed = train_df[
        GAN_FEATURES
    ].copy()

    # --------------------------------------------------------
    # Make sure all variables are numeric
    # --------------------------------------------------------

    for col in GAN_FEATURES:

        transformed[col] = pd.to_numeric(
            transformed[col],
            errors="coerce"
        )

    if transformed.isnull().any().any():

        print(
            transformed.isnull().sum()
        )

        raise ValueError(
            "Missing or non-numeric values found "
            "in GAN input."
        )

    # --------------------------------------------------------
    # Check positivity before log1p
    # --------------------------------------------------------

    for col in LOG_FEATURES:

        min_value = transformed[
            col
        ].min()

        print(
            f"{col}: minimum before log1p = "
            f"{min_value}"
        )

        if min_value < 0:

            raise ValueError(
                f"{col} contains negative values. "
                "Cannot safely apply log1p."
            )

    # --------------------------------------------------------
    # log1p transformation
    # --------------------------------------------------------

    for col in LOG_FEATURES:

        transformed[col] = np.log1p(
            transformed[col]
        )

    return transformed


# ============================================================
# 9. Train GAN
# ============================================================

def train_tabular_gan(
    X_real,
    epochs=200,
    batch_size=256,
    noise_dim=32,
    hidden_dim=128,
    lr=2e-4,
    beta1=0.5,
    beta2=0.9
):

    X_tensor = torch.tensor(
        X_real,
        dtype=torch.float32
    )

    dataset = TensorDataset(
        X_tensor
    )

    loader = DataLoader(
        dataset,
        batch_size=batch_size,
        shuffle=True,
        drop_last=True
    )

    data_dim = X_real.shape[1]

    G = TabGenerator(
        noise_dim=noise_dim,
        out_dim=data_dim,
        hidden_dim=hidden_dim
    ).to(DEVICE)

    D = TabDiscriminator(
        in_dim=data_dim,
        hidden_dim=hidden_dim
    ).to(DEVICE)

    criterion = nn.BCELoss()

    optimizer_G = optim.Adam(
        G.parameters(),
        lr=lr,
        betas=(
            beta1,
            beta2
        )
    )

    optimizer_D = optim.Adam(
        D.parameters(),
        lr=lr,
        betas=(
            beta1,
            beta2
        )
    )

    print("\n" + "=" * 70)
    print("Training Tabular GAN")
    print("=" * 70)

    print(
        "Training samples:",
        len(X_real)
    )

    print(
        "Feature dimension:",
        data_dim
    )

    print(
        "Noise dimension:",
        noise_dim
    )

    print(
        "Epochs:",
        epochs
    )

    print(
        "Batch size:",
        batch_size
    )

    for epoch in range(
        epochs
    ):

        g_loss_total = 0.0

        d_loss_total = 0.0

        n_batches = 0

        for (
            real_batch,
        ) in loader:

            real_batch = real_batch.to(
                DEVICE
            )

            current_batch_size = (
                real_batch.size(0)
            )

            real_labels = torch.ones(
                current_batch_size,
                1,
                device=DEVICE
            )

            fake_labels = torch.zeros(
                current_batch_size,
                1,
                device=DEVICE
            )

            # =================================================
            # Discriminator
            # =================================================

            optimizer_D.zero_grad()

            real_output = D(
                real_batch
            )

            d_real_loss = criterion(
                real_output,
                real_labels
            )

            z = torch.randn(
                current_batch_size,
                noise_dim,
                device=DEVICE
            )

            fake_batch = G(z)

            fake_output = D(
                fake_batch.detach()
            )

            d_fake_loss = criterion(
                fake_output,
                fake_labels
            )

            d_loss = (
                d_real_loss
                + d_fake_loss
            )

            d_loss.backward()

            optimizer_D.step()

            # =================================================
            # Generator
            # =================================================

            optimizer_G.zero_grad()

            z = torch.randn(
                current_batch_size,
                noise_dim,
                device=DEVICE
            )

            generated_batch = G(z)

            generated_output = D(
                generated_batch
            )

            g_loss = criterion(
                generated_output,
                real_labels
            )

            g_loss.backward()

            optimizer_G.step()

            g_loss_total += (
                g_loss.item()
            )

            d_loss_total += (
                d_loss.item()
            )

            n_batches += 1

        if n_batches > 0:

            g_loss_avg = (
                g_loss_total
                / n_batches
            )

            d_loss_avg = (
                d_loss_total
                / n_batches
            )

        else:

            g_loss_avg = np.nan

            d_loss_avg = np.nan

        if (
            epoch == 0
            or (epoch + 1) % 10 == 0
            or epoch == epochs - 1
        ):

            print(
                f"Epoch "
                f"[{epoch + 1:3d}/{epochs}] "
                f"D Loss: "
                f"{d_loss_avg:.4f} | "
                f"G Loss: "
                f"{g_loss_avg:.4f}"
            )

    print(
        "\nGAN training completed."
    )

    return G


# ============================================================
# 10. Generate synthetic data
# ============================================================

def generate_synthetic_features(
    generator,
    scaler,
    n_samples,
    noise_dim=32
):

    generator.eval()

    generated_batches = []

    remaining = n_samples

    with torch.no_grad():

        while remaining > 0:

            current_batch = min(
                1024,
                remaining
            )

            z = torch.randn(
                current_batch,
                noise_dim,
                device=DEVICE
            )

            fake = generator(z)

            generated_batches.append(
                fake.cpu().numpy()
            )

            remaining -= current_batch

    X_fake_scaled = np.vstack(
        generated_batches
    )

    # Reverse StandardScaler
    X_fake_transformed = (
        scaler.inverse_transform(
            X_fake_scaled
        )
    )

    return X_fake_transformed


# ============================================================
# 11. Convert transformed synthetic data
#     back to original scale
# ============================================================

def inverse_transform_claim_features(
    X_fake_transformed
):

    synthetic = pd.DataFrame(
        X_fake_transformed,
        columns=GAN_FEATURES
    )

    # --------------------------------------------------------
    # Reverse log1p transformation
    #
    # IMPORTANT:
    # We do NOT clip negative GAN output here.
    #
    # If transformed GAN output is negative enough,
    # expm1 can produce a value below zero.
    #
    # We deliberately keep this behavior visible because
    # we want to diagnose GAN quality rather than hide it.
    # --------------------------------------------------------

    for col in LOG_FEATURES:

        synthetic[col] = np.expm1(
            synthetic[col]
        )

    return synthetic


# ============================================================
# 12. Fidelity analysis
# ============================================================

def calculate_fidelity(
    real_df,
    synthetic_df
):

    rows = []

    quantiles = [
        0.01,
        0.05,
        0.25,
        0.50,
        0.75,
        0.90,
        0.95,
        0.99
    ]

    for col in GAN_FEATURES:

        real = pd.to_numeric(
            real_df[col],
            errors="coerce"
        ).dropna().to_numpy()

        synthetic = pd.to_numeric(
            synthetic_df[col],
            errors="coerce"
        ).dropna().to_numpy()

        ks_stat, ks_p = ks_2samp(
            real,
            synthetic
        )

        row = {

            "variable": col,

            "real_mean":
                np.mean(real),

            "synthetic_mean":
                np.mean(synthetic),

            "real_std":
                np.std(real),

            "synthetic_std":
                np.std(synthetic),

            "real_min":
                np.min(real),

            "synthetic_min":
                np.min(synthetic),

            "real_max":
                np.max(real),

            "synthetic_max":
                np.max(synthetic),

            "ks_statistic":
                ks_stat,

            "ks_pvalue":
                ks_p,

            "real_negative_pct":
                np.mean(real < 0),

            "synthetic_negative_pct":
                np.mean(synthetic < 0)
        }

        for q in quantiles:

            q_name = (
                f"q{int(q * 100):02d}"
            )

            row[
                f"real_{q_name}"
            ] = np.quantile(
                real,
                q
            )

            row[
                f"synthetic_{q_name}"
            ] = np.quantile(
                synthetic,
                q
            )

        rows.append(row)

    return pd.DataFrame(
        rows
    )


# ============================================================
# 13. Main pipeline
# ============================================================

def run_claim_gan():

    print("\n" + "=" * 70)
    print("CLAIM GAN PIPELINE - VERSION 2")
    print("=" * 70)

    # ========================================================
    # Load data
    # ========================================================

    train_claims = pd.read_csv(
        TRAIN_FILE
    )

    test_claims = pd.read_csv(
        TEST_FILE
    )

    print(
        "\nTrain shape:",
        train_claims.shape
    )

    print(
        "Test shape:",
        test_claims.shape
    )

    # ========================================================
    # Check columns
    # ========================================================

    missing_train = [
        c
        for c in ALL_CLAIM_COLUMNS
        if c not in train_claims.columns
    ]

    missing_test = [
        c
        for c in ALL_CLAIM_COLUMNS
        if c not in test_claims.columns
    ]

    if missing_train:

        raise ValueError(
            "Missing train columns: "
            + str(missing_train)
        )

    if missing_test:

        raise ValueError(
            "Missing test columns: "
            + str(missing_test)
        )

    # ========================================================
    # Transform GAN input
    # ========================================================

    transformed_df = (
        transform_claim_features(
            train_claims
        )
    )

    X_transformed = (
        transformed_df[
            GAN_FEATURES
        ].to_numpy(
            dtype=np.float32
        )
    )

    # ========================================================
    # StandardScaler
    # ========================================================

    scaler = StandardScaler()

    X_real_scaled = scaler.fit_transform(
        X_transformed
    )

    print(
        "\nGAN input standardized."
    )

    # ========================================================
    # Determine synthetic sample size
    # ========================================================

    n_real = len(
        train_claims
    )

    n_synthetic = int(
        n_real
        * SYNTHETIC_CLAIMS_RATIO
    )

    print(
        "\nReal training claims:",
        n_real
    )

    print(
        "Synthetic claims:",
        n_synthetic
    )

    print(
        "Synthetic ratio:",
        SYNTHETIC_CLAIMS_RATIO
    )

    # ========================================================
    # Train GAN
    # ========================================================

    generator = train_tabular_gan(
        X_real=X_real_scaled,

        epochs=GAN_EPOCHS,

        batch_size=GAN_BATCH_SIZE,

        noise_dim=NOISE_DIM,

        hidden_dim=GAN_HIDDEN_DIM,

        lr=GAN_LR,

        beta1=GAN_BETA1,

        beta2=GAN_BETA2
    )

    # ========================================================
    # Generate synthetic data
    # ========================================================

    X_fake_transformed = (
        generate_synthetic_features(
            generator=generator,

            scaler=scaler,

            n_samples=n_synthetic,

            noise_dim=NOISE_DIM
        )
    )

    # ========================================================
    # Return to original scale
    # ========================================================

    synthetic_claims = (
        inverse_transform_claim_features(
            X_fake_transformed
        )
    )

    # ========================================================
    # Add synthetic claim ID
    # ========================================================

    synthetic_claims.insert(
        0,
        "claim_no",
        [
            f"syn_claim_{i}"
            for i in range(
                n_synthetic
            )
        ]
    )

    # ========================================================
    # Match original column order
    # ========================================================

    synthetic_claims = (
        synthetic_claims[
            train_claims.columns
        ]
    )

    # ========================================================
    # Print synthetic preview
    # ========================================================

    print(
        "\n" + "=" * 70
    )

    print(
        "Synthetic claim preview"
    )

    print(
        "=" * 70
    )

    print(
        synthetic_claims.head(10)
    )

    # ========================================================
    # Negative-value diagnostics
    # ========================================================

    print(
        "\n" + "=" * 70
    )

    print(
        "Synthetic data validity diagnostics"
    )

    print(
        "=" * 70
    )

    for col in LOG_FEATURES:

        negative_pct = (
            np.mean(
                synthetic_claims[col]
                < 0
            )
            * 100
        )

        print(
            f"{col}: "
            f"{negative_pct:.4f}% negative"
        )

    # ========================================================
    # Save synthetic claims
    # ========================================================

    synthetic_claims.to_csv(
        OUTPUT_SYNTHETIC,
        index=False
    )

    print(
        "\nSynthetic claims saved:"
    )

    print(
        OUTPUT_SYNTHETIC
    )

    # ========================================================
    # Fidelity analysis
    # ========================================================

    print(
        "\n" + "=" * 70
    )

    print(
        "GAN fidelity analysis"
    )

    print(
        "=" * 70
    )

    fidelity = calculate_fidelity(
        real_df=train_claims,
        synthetic_df=synthetic_claims
    )

    pd.set_option(
        "display.max_columns",
        None
    )

    print(
        fidelity
    )

    fidelity.to_csv(
        OUTPUT_FIDELITY,
        index=False
    )

    print(
        "\nFidelity report saved:"
    )

    print(
        OUTPUT_FIDELITY
    )

    # ========================================================
    # 1:1 augmentation
    # ========================================================

    print(
        "\n" + "=" * 70
    )

    print(
        "1:1 GAN augmentation"
    )

    print(
        "=" * 70
    )

    augmented_train = pd.concat(
        [
            train_claims,
            synthetic_claims
        ],
        ignore_index=True
    )

    print(
        "Original train:",
        len(train_claims)
    )

    print(
        "Synthetic:",
        len(synthetic_claims)
    )

    print(
        "Augmented train:",
        len(augmented_train)
    )

    # ========================================================
    # Save augmented data
    # ========================================================

    augmented_train.to_csv(
        OUTPUT_AUGMENTED,
        index=False
    )

    print(
        "\nAugmented training data saved:"
    )

    print(
        OUTPUT_AUGMENTED
    )

    # ========================================================
    # LightGBM
    # ========================================================

    print(
        "\n" + "=" * 70
    )

    print(
        "LightGBM downstream prediction"
    )

    print(
        "=" * 70
    )

    feature_columns = [
        c
        for c in augmented_train.columns
        if c not in [
            "claim_no",
            "claim_size"
        ]
    ]

    X_all = augmented_train[
        feature_columns
    ].copy()

    y_all = augmented_train[
        "claim_size"
    ].astype(float)

    X_test = test_claims[
        feature_columns
    ].copy()

    y_test = test_claims[
        "claim_size"
    ].astype(float)

    # --------------------------------------------------------
    # Numeric conversion
    # --------------------------------------------------------

    for col in feature_columns:

        X_all[col] = pd.to_numeric(
            X_all[col],
            errors="coerce"
        )

        X_test[col] = pd.to_numeric(
            X_test[col],
            errors="coerce"
        )

    if X_all.isnull().any().any():

        raise ValueError(
            "NaN found in LightGBM training features."
        )

    if X_test.isnull().any().any():

        raise ValueError(
            "NaN found in LightGBM test features."
        )

    # ========================================================
    # Train / validation split
    # ========================================================

    X_train, X_val, y_train, y_val = (
        train_test_split(
            X_all,
            y_all,
            test_size=VALIDATION_SIZE,
            random_state=42
        )
    )

    print(
        "\nTraining subset:",
        len(X_train)
    )

    print(
        "Validation subset:",
        len(X_val)
    )

    print(
        "Test set:",
        len(X_test)
    )

    # ========================================================
    # LightGBM model
    # ========================================================

    model = LGBMRegressor(

        n_estimators=
            LGB_N_ESTIMATORS,

        learning_rate=
            LGB_LEARNING_RATE,

        num_leaves=
            LGB_NUM_LEAVES,

        objective=
            "regression",

        random_state=
            LGB_RANDOM_STATE,

        n_jobs=-1
    )

    model.fit(

        X_train,

        y_train,

        eval_set=[
            (
                X_val,
                y_val
            )
        ],

        eval_metric="l2",

        callbacks=[
            lgb.early_stopping(
                EARLY_STOPPING_ROUNDS,
                verbose=True
            ),

            lgb.log_evaluation(
                period=50
            )
        ]
    )

    # ========================================================
    # Test prediction
    # ========================================================

    y_pred = model.predict(
        X_test
    )

    # Keep downstream claim predictions non-negative.
    #
    # This is NOT applied to GAN synthetic training data.
    # It only prevents the final regression model from
    # producing physically meaningless negative claim amounts.
    y_pred = np.maximum(
        y_pred,
        0
    )

    # ========================================================
    # Metrics
    # ========================================================

    mse = mean_squared_error(
        y_test,
        y_pred
    )

    rmse = np.sqrt(
        mse
    )

    mae = mean_absolute_error(
        y_test,
        y_pred
    )

    true_total = np.sum(
        y_test.to_numpy()
    )

    pred_total = np.sum(
        y_pred
    )

    if abs(true_total) > 1e-12:

        rr = (
            pred_total
            / true_total
        )

    else:

        rr = np.nan

    print(
        "\n" + "=" * 70
    )

    print(
        "FINAL TEST RESULTS"
    )

    print(
        "=" * 70
    )

    print(
        f"MSE  : {mse:.6f}"
    )

    print(
        f"RMSE : {rmse:.6f}"
    )

    print(
        f"MAE  : {mae:.6f}"
    )

    print(
        f"RR   : {rr:.6f}"
    )

    # ========================================================
    # Save predictions
    # ========================================================

    prediction_output = pd.DataFrame(
        {
            "claim_no":
                test_claims[
                    "claim_no"
                ],

            "true_claim_size":
                y_test.to_numpy(),

            "pred_claim_size":
                y_pred
        }
    )

    prediction_output.to_csv(
        OUTPUT_PREDICTIONS,
        index=False
    )

    print(
        "\nPrediction file saved:"
    )

    print(
        OUTPUT_PREDICTIONS
    )

    # ========================================================
    # Final summary
    # ========================================================

    print(
        "\n" + "=" * 70
    )

    print(
        "PIPELINE SUMMARY"
    )

    print(
        "=" * 70
    )

    print(
        "Original training claims:",
        len(train_claims)
    )

    print(
        "Synthetic claims:",
        len(synthetic_claims)
    )

    print(
        "Augmented training claims:",
        len(augmented_train)
    )

    print(
        "Test claims:",
        len(test_claims)
    )

    print(
        "\nGAN features:"
    )

    for col in GAN_FEATURES:

        print(
            "  -",
            col
        )

    print(
        "\nLog-transformed features:"
    )

    for col in LOG_FEATURES:

        print(
            "  -",
            col
        )

    print(
        "\nRaw-scale features:"
    )

    for col in RAW_FEATURES:

        print(
            "  -",
            col
        )

    print(
        "\nno_payment:"
    )

    print(
        "  - no rounding"
    )

    print(
        "  - no clipping"
    )

    print(
        "\nSynthetic data are generated directly "
        "by the GAN and merged 1:1 with the "
        "original training data."
    )

    print(
        "\nPipeline completed successfully."
    )


# ============================================================
